import java.util.Collection;
import java.util.Collections;
import java.util.ArrayList;
import java.util.List;

public class CollectionDemo {
    public static void processItems(Collection<String> items) {
        // Using the Collection interface method
        if (!items.isEmpty()) {
            System.out.println("Total elements: " + items.size());
        }
    }

    public static void main(String[] args) {
        List<String> mutableList = new ArrayList<>();
        mutableList.add("Delta");
        mutableList.add("Alpha");

        // Using the Collections utility class to sort
        Collections.sort(mutableList);

        // Creating an unmodifiable view using Collections utility
        Collection<String> readOnlyView = Collections.unmodifiableCollection(mutableList);

        processItems(readOnlyView);
    }
}
